mapper.select:
/* SQL ID : co.kr.abacus.nds.common.dao.SecuritySupportDao.getRoleMenuScrn SQL 명 : 사용자의 역할-메뉴-화면 매핑 정보 조회(관리자 시스템용도) */ WITH RECURSIVE CTE AS ( SELECT MNU.menu_id, MNU.menu_name, MNU.parent_menu_id AS HPOS_MENU_ID, 1 AS LVL, MNU.menu_name AS MENU_PATH, CAST(MNU.sort AS CHAR) AS MENU_ORDER, MNU.menu_path AS MENU_URL, MNU.menu_id AS MENU_IDX FROM tb_menu MNU INNER JOIN tb_auth_menu_map MAP ON MNU.menu_id = MAP.menu_id INNER JOIN tb_auth AUTH ON MAP.auth_id = AUTH.auth_id WHERE MAP.auth_id IN
#{item.roleId}
AND MNU.parent_menu_id IS NULL
UNION ALL
SELECT B.menu_id, B.menu_name, B.parent_menu_id AS HPOS_MENU_ID, C.LVL + 1 AS LVL, CONCAT(C.MENU_PATH, ' > ', B.menu_name) AS MENU_PATH, CONCAT(C.MENU_ORDER, ',', B.sort) AS MENU_ORDER, B.menu_path AS MENU_URL, B.menu_id AS MENU_IDX FROM tb_menu B INNER JOIN tb_auth_menu_map MAP ON B.menu_id = MAP.menu_id INNER JOIN tb_auth AUTH ON MAP.auth_id = AUTH.auth_id INNER JOIN CTE C ON B.parent_menu_id = C.menu_id ) SELECT RESULT.menu_id AS MENU_ID, COALESCE(RESULT.HPOS_MENU_ID, '#') AS HPOS_MENU_ID, RESULT.MENU_IDX, RESULT.MENU_ORDER, RESULT.menu_name AS MENU_NM, RESULT.LVL, RESULT.MENU_PATH, RESULT.MENU_URL FROM CTE RESULT LEFT OUTER JOIN tb_auth_menu_map MAP ON RESULT.menu_id = MAP.menu_id AND MAP.auth_id IN
#{item.roleId}
ORDER BY RESULT.MENU_IDX

/* SQL ID : co.kr.abacus.nds.common.dao.SecuritySupportDao.getRoleMenuScrnRoleUse SQL 명 : 사용자의 역할-메뉴-화면 매핑 정보 조회(모든 사용자 용도) */ WITH RECURSIVE CTE AS ( SELECT MNU.menu_id, MNU.menu_name, MNU.parent_menu_id AS HPOS_MENU_ID, 1 AS LVL, MNU.menu_name AS MENU_PATH, CAST(MNU.sort AS CHAR) AS MENU_ORDER, MNU.menu_path AS MENU_URL, MNU.menu_id AS MENU_IDX FROM tb_menu MNU INNER JOIN tb_auth_menu_map MAP ON MNU.menu_id = MAP.menu_id INNER JOIN tb_auth AUTH ON MAP.auth_id = AUTH.auth_id WHERE MAP.auth_id IN
#{item.roleId}
AND MNU.parent_menu_id IS NULL
UNION ALL
SELECT B.menu_id, B.menu_name, B.parent_menu_id AS HPOS_MENU_ID, C.LVL + 1 AS LVL, CONCAT(C.MENU_PATH, ' > ', B.menu_name) AS MENU_PATH, CONCAT(C.MENU_ORDER, ',', B.sort) AS MENU_ORDER, B.menu_path AS MENU_URL, B.menu_id AS MENU_IDX FROM tb_menu B INNER JOIN tb_auth_menu_map MAP ON B.menu_id = MAP.menu_id INNER JOIN tb_auth AUTH ON MAP.auth_id = AUTH.auth_id INNER JOIN CTE C ON B.parent_menu_id = C.menu_id ) SELECT RESULT.menu_id AS MENU_ID, COALESCE(RESULT.HPOS_MENU_ID, '#') AS HPOS_MENU_ID, RESULT.MENU_IDX, RESULT.MENU_ORDER, RESULT.menu_name AS MENU_NM, RESULT.LVL, RESULT.MENU_PATH, RESULT.MENU_URL FROM CTE RESULT LEFT OUTER JOIN tb_auth_menu_map MAP ON RESULT.menu_id = MAP.menu_id AND MAP.auth_id IN
#{item.roleId}
ORDER BY RESULT.MENU_IDX
